import numpy as np, pandas as pd
from alphacrafter.sim.utils import get_index_daily_data, get_stock_daily_data

U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
def get(s):
    for f in (get_index_daily_data,get_stock_daily_data):
        try:
            x=f(s,days=2400)
            if x is not None and len(x): return x[['date','close']].drop_duplicates('date').set_index('date')['close']
        except Exception: pass
    return pd.Series(dtype=float)
px={s:get(s) for s in U}; dxy=get_index_daily_data('DXY',days=2400)
dxy=dxy[['date','close']].drop_duplicates('date').set_index('date')['close'] if dxy is not None else pd.Series(dtype=float)
R=pd.DataFrame({s:v.pct_change() for s,v in px.items()}); m=dxy.pct_change().rename('m')
# daily factor available at t: negative trailing DXY beta, designed to prefer assets that benefit when USD weakens
L=60
f=pd.DataFrame(index=R.index,columns=U,dtype=float)
for s in U:
    cov=R[s].rolling(L,min_periods=45).cov(m); var=m.rolling(L,min_periods=45).var()
    f[s]=-cov/var
# forward one-day return and cross-sectional IC
fr=R.shift(-1); obs=[]; ranks=[]
for dt in f.index:
    z=pd.concat([f.loc[dt],fr.loc[dt]],axis=1).dropna()
    if len(z)>=8:
        obs.append(z.iloc[:,0].corr(z.iloc[:,1],method='spearman'))
        ranks.append(z.iloc[:,0].rank(pct=True))
ic=pd.Series(obs).dropna(); print('dates',len(ic),'avgN',np.mean([len(pd.concat([f.loc[d],fr.loc[d]],axis=1).dropna()) for d in f.index if len(pd.concat([f.loc[d],fr.loc[d]],axis=1).dropna())>=8]))
print('IC %.6f ICIR %.6f hit %.4f'%(ic.mean(),ic.mean()/ic.std(),(ic>0).mean()))
for h in [5,10]:
    x=[]
    fh=R.shift(-h).rolling(h).sum()
    for dt in f.index:
      z=pd.concat([f.loc[dt],fh.loc[dt]],axis=1).dropna()
      if len(z)>=8:x.append(z.iloc[:,0].corr(z.iloc[:,1],method='spearman'))
    x=pd.Series(x).dropna();print(h,'IC %.6f ICIR %.6f n %d'%(x.mean(),x.mean()/x.std(),len(x)))
for a,b in [(2020,2022),(2023,2024),(2025,2026)]:
 x=ic[ic.index if False else slice(None)] # placeholder
# date-index IC regime reconstruction
vals=[]
for dt in f.index:
 z=pd.concat([f.loc[dt],fr.loc[dt]],axis=1).dropna()
 if len(z)>=8: vals.append((dt,z.iloc[:,0].corr(z.iloc[:,1],method='spearman')))
q=pd.Series(dict(vals));
for y in range(2020,2027):
 x=q[q.index.year==y];
 if len(x):print(y,len(x),round(x.mean(),5),round(x.mean()/x.std(),4))
print('coverage',f.notna().sum().sum()/f.size)
# rank turnover
rr=f.rank(axis=1,pct=True); print('turnover',rr.diff().abs().mean().mean())
# save signal artifact for provenance
out=f.loc['2020-01-01':'2026-07-15'].reset_index().rename(columns={'index':'date'}); out['date']=out['date'].astype(str); out.to_csv('scripts/miner_3_20260730_dxy_beta_signal.csv',index=False)

