import pandas as pd, numpy as np
from scipy.stats import spearmanr
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']; END=pd.Timestamp('2026-07-15')
def load(s,macro=False):
 p=('../persistent/index_data/' if macro else '../persistent/stock_data/')+s+'.csv';d=pd.read_csv(p);d['date']=pd.to_datetime(d['date']);return d[d.date<=END].sort_values('date').drop_duplicates('date').set_index('date')['close'].astype(float)
M=load('DXY',1).pct_change();R={s:load(s).pct_change() for s in U}
def factor(a,m,L=60):
 z=pd.concat([a.rename('a'),m.rename('m')],axis=1,join='inner').dropna();x=z.a.values;y=z.m.values;o=np.full(len(z),np.nan)
 for i in range(44,len(z)):
  lo=max(0,i-L+1);v=np.var(y[lo:i+1],ddof=1)
  if v>1e-16:o[i]=-np.cov(x[lo:i+1],y[lo:i+1],ddof=1)[0,1]/v
 return pd.Series(o,index=z.index)
for L in [20,40,60,90,120]:
 rows=[]
 for s in U:
  z=pd.concat([R[s].rename('a'),M.rename('m')],axis=1,join='inner').dropna();f=factor(R[s],M,L)
  for dt in z.index[:-1]:
   if np.isfinite(f.get(dt,np.nan)):rows.append((dt,s,f[dt],z.a.shift(-1).get(dt)))
 d=pd.DataFrame(rows,columns=['date','s','f','y']).dropna();ics=[]
 for dt,g in d.groupby('date'):
  if len(g)>=8:ics.append(spearmanr(g.f,g.y).statistic)
 a=np.array(ics);print('L',L,'dates',len(a),'avgN',round(d.groupby('date').size().mean(),2),'IC',round(a.mean(),6),'ICIR',round(a.mean()/a.std(ddof=1),6),'hit',round((a>0).mean(),4))

import pandas as pd, numpy as np
from scipy.stats import spearmanr
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']; END=pd.Timestamp('2026-07-15')
def load(s):
 d=pd.read_csv('../persistent/stock_data/'+s+'.csv');d.date=pd.to_datetime(d.date);d=d[d.date<=END].sort_values('date').drop_duplicates('date').set_index('date');return d
# Range-shock reversal: fade the prior close-to-close return only when its true range is unusually large.
for L in [10,20,40]:
 rows=[]
 for s in U:
  d=load(s); r=d.close.pct_change(); tr=(d.high-d.low)/d.close.shift(1); shock=tr/(tr.rolling(L,min_periods=max(5,L//2)).median())
  f=-(r*shock).shift(0) # signal at completed date, next return target
  y=r.shift(-1)
  z=pd.concat([f.rename('f'),y.rename('y')],axis=1).dropna()
  for dt,v in z.iterrows(): rows.append((dt,s,v.f,v.y))
 q=pd.DataFrame(rows,columns=['date','s','f','y']);ics=[]; ns=[]; ranks=[]
 for dt,g in q.groupby('date'):
  g=g[np.isfinite(g.f)&np.isfinite(g.y)]
  if len(g)>=8:
   ics.append(spearmanr(g.f,g.y).statistic);ns.append(len(g)); ranks.append(g.f.rank().corr(g.y.rank()))
 a=np.array(ics);print('L',L,'dates',len(a),'avgN',round(np.mean(ns),2),'coverage',round(len(a)/(END-pd.Timestamp('2020-01-01')).days,4),'IC',round(a.mean(),6),'ICIR',round(a.mean()/a.std(ddof=1),6),'hit',round((a>0).mean(),4),'turnover_proxy',round(np.mean([1]),4))
 for lo,hi in [('2020','2022'),('2023','2024'),('2025','2026')]:
  x=a[[str(d)[:4]>=lo and str(d)[:4]<=hi for d in sorted(q[q.date.isin([])].date.unique())]] if False else None

import pandas as pd,numpy as np
from scipy.stats import spearmanr
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']; END=pd.Timestamp('2026-07-15')
def load(s):
 d=pd.read_csv('../persistent/stock_data/'+s+'.csv');d.date=pd.to_datetime(d.date);return d[d.date<=END].sort_values('date').drop_duplicates('date').set_index('date')
D={s:load(s) for s in U}; sig={}; ret={}
for s,d in D.items():
 r=d.close.pct_change(); ret[s]=r
 tr=(d.high-d.low)/d.close.shift(1); sig[s]=-(r*tr/tr.rolling(20,min_periods=10).median())
rows=[]
for s in U:
 for dt in sig[s].index:
  f=sig[s].get(dt); y=ret[s].shift(-1).get(dt)
  if np.isfinite(f) and np.isfinite(y): rows.append((dt,s,f,y))
q=pd.DataFrame(rows,columns=['date','s','f','y']);ics=[]
for dt,g in q.groupby('date'):
 if len(g)>=8: ics.append((dt,spearmanr(g.f,g.y).statistic))
a=np.array([x[1] for x in ics]);print('candidate L20 dates',len(a),'avgN',q.groupby('date').size().mean(),'IC',a.mean(),'ICIR',a.mean()/a.std(ddof=1),'hit',(a>0).mean(),'coverage',len(a)/len(set(q.date)))
for lo,hi in [(2020,2022),(2023,2024),(2025,2026)]:
 x=np.array([v for d,v in ics if lo<=d.year<=hi]);print('regime',lo,hi,'n',len(x),'IC',x.mean(),'ICIR',x.mean()/x.std(ddof=1))
# decay
for h in [1,5,10,20]:
 rr=[]
 for s in U:
  y=D[s].close.pct_change(h).shift(-h); z=pd.concat([sig[s],y],axis=1).dropna();
  for dt,v in z.iterrows(): rr.append((dt,s,v.iloc[0],v.iloc[1]))
 z=pd.DataFrame(rr,columns=['date','s','f','y']); x=[]
 for dt,g in z.groupby('date'):
  if len(g)>=8:x.append(spearmanr(g.f,g.y).statistic)
 x=np.array(x);print('decay',h,'IC',x.mean(),'ICIR',x.mean()/x.std(ddof=1))
# pooled rank correlations with simple production analogues
allc=[];clv=[];rev=[];mom=[]
for s,d in D.items():
 r=d.close.pct_change(); tr=(d.high-d.low)/d.close.shift(1)
 for dt in sig[s].index:
  vals=[sig[s].get(dt), -(2*(d.close-d.low)/(d.high-d.low)-1).get(dt), -r.rolling(5).sum().get(dt), (r.rolling(20).sum()/r.rolling(20).std()).get(dt)]
  if all(np.isfinite(vals)):allc.append(vals)
c=np.array(allc);print('pooled Spearman corr candidate vs CLV/rev/mom',*[spearmanr(c[:,0],c[:,i]).statistic for i in [1,2,3]])

